def pre(vals):
    # Valid inputs: list of 0-6 integers, each between -10 and 10
    if len(vals) > 6:
        return False
    for v in vals:
        if v < -10 or v > 10:
            return False
    return True

def post(vals, result):
    # Compute the expected result independently
    expected = []
    if len(vals) > 0:
        running_max = vals[0]
        expected.append(running_max)
        for i in range(1, len(vals)):
            if vals[i] > running_max:
                running_max = vals[i]
            expected.append(running_max)

    # Check that result matches expected
    if len(result) != len(expected):
        return False
    for i in range(len(result)):
        if result[i] != expected[i]:
            return False

    return True
